+                                      ? min(local_equal,
+                                            remaining - offsets.equal)
+                                      : 0;
+  for (uint32_t i = tx; i < equal_to_write; i += hist4096::kBlockSize) {
+    row_output[offsets.total_above + offsets.equal + i] =
+        equal_indices[i] + my_start;
