+  const uint32_t coarse_above = smem->match.above_count;
+  const auto probe_status = probe_arbitrary_fp32_overflow<TopK, CS, UseResident>(
+      row_input, my_start, my_len, coarse_bin, coarse_above, smem, s_topk);
