+    topk_histogram_4096::exact_topk_rescan<
+        MaxK, BlockSize, true, VecSize, true, 1, CandidateCapacity>(
+        scores, output, length, dynamic_smem, threshold_bin << 21, remaining);
+  }
+  return true;
